/// <summary>
///    AVA <c>avaCreateActivity</c> method.
/// </summary>
/// <param name="_table">
///    <c>Common</c> as type
/// </param>
/// <param name="_responsibleWorker">
///    <c>HcmWorkerRecId</c> as type
/// </param>
/// <param name="_isBatchJob">
///    <c>boolean</c> as type
/// </param>
/// <param name="_templateActivity">
///    <c>smmActivities</c> as type
/// </param>
/// <param name="_isCalledFromWorkflow">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>smmActivities</c> as return value
/// </returns>
public static smmActivities avaCreateActivity(  Common          _table, 
                                                HcmWorkerRecId  _responsibleWorker,
                                                boolean         _isBatchJob             = false,
                                                smmActivities   _templateActivity       = null,
                                                boolean         _isCalledFromWorkflow   = false )
{
    smmActivities       retVal;

    //smmActivityCreate   creator;

    KCS_KBVBuildingProjectTable locKCS_KBVBuildingProjectTable;
    HcmWorker                   locHCMWorker;


    switch (_table.TableId)
    {
        case tableNum(KCS_KBVBuildingProjectTable):
            locKCS_KBVBuildingProjectTable  = _table;
            locHCMWorker                    = HCMWorker::find(_responsibleWorker);

            //ToDo: set Reponsibilty
            /*
            creator = new smmActivityCreate(_table, _isBatchJob, _templateActivity, _isCalledFromWorkflow);
            if (smmActivityCreate::isTemplateActivity(_table, _templateActivity))
            {
                creator.save();
            }
            else
            {
                smmActivityCreate::checkAndCreateActivity(_table, _isBatchJob, _templateActivity, _isCalledFromWorkflow, creator);
            }
            retVal = creator.getActivity();
            */
            //ToDo: and replace this with it
            retVal = smmActivityCreate::createActivity( _table,
                                                        _isBatchJob,
                                                        _templateActivity,
                                                        _isCalledFromWorkflow   );
            break;

        default:
            retVal = smmActivityCreate::createActivity( _table,
                                                        _isBatchJob,
                                                        _templateActivity,
                                                        _isCalledFromWorkflow   );
    }
    return retVal;
}
